package com.andye.warmod.antiair;import com.andye.warmod.icbm.IcbmChunkTicketRegistry;import java.util.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.ChunkPos;import net.minecraft.world.phys.Vec3;public final class AntiAirChunkTicketController{private final Set<ChunkPos> held=new HashSet<>();public void updateFallback(ServerLevel l,Vec3 p){Set<ChunkPos> next=IcbmChunkTicketRegistry.window(IcbmChunkTicketRegistry.chunk(p),1);for(ChunkPos c:next)if(!held.contains(c))IcbmChunkTicketRegistry.acquire(l,c);for(ChunkPos c:new HashSet<>(held))if(!next.contains(c))IcbmChunkTicketRegistry.release(l,c);held.clear();held.addAll(next);}public void releaseAll(ServerLevel l){IcbmChunkTicketRegistry.releaseAll(l,Set.copyOf(held));held.clear();}}